const connect = async (login = cluster.user, role?: 'authenticated' | 'ot_v3_method_reader' | 'postgres') => {
  const connection = await LocalPgConnection.connect(cluster, login); connections.add(connection)
  // Capture the genuine login's own birth before NOINHERIT SET ROLE hides it.
  const rows = await connection.query(identitySql)
  assert.equal(rows.length, 1); assert.ok(rows[0]!.pid && rows[0]!.birth)
  assert.equal(rows[0]!.session_user, login); assert.equal(rows[0]!.current_user, login)
  identities.set(connection, Object.freeze({ pid: rows[0]!.pid, birth: rows[0]!.birth }))
  if (role) await connection.query('SET ROLE ' + role)
  if (login === MA1_AUTH.humanLogin || login === MA1_AUTH.readerLogin) {
    assert.deepEqual(await connection.query('SELECT pg_catalog.pg_backend_pid()::text AS pid,session_user::text AS session_user,current_user::text AS current_user'),
      [{ pid: rows[0]!.pid, session_user: login, current_user: role! }])
  }
  return connection
}
